for(let i=0;i<16;i++){const a=i*Math.PI/8;box(-5+Math.cos(a)*2,.16,-5+Math.sin(a)*2,.1,.08,.1,'#ddc795');}box(-5,0,-5,.32,3,.32,'#a38d62');for(let i=0;i<7;i++){const a=i*Math.PI*2/7;crystal(-5+Math.cos(a)*1.1,3.2+Math.sin(i)*.4,-5+Math.sin(a)*1.1,.9,1.7,i%2?'#b9cf99':'#d4c08b');}crystal(-5,5+Math.sin(clock)*.12,-5,.17,.38,'#f4dfaa');
